class SunSeeker:
    def __init__(self):
        self.dream = True

    def find_sun(self):
        if self.dream:
            return "Солнце здесь. Оно — в каждом запросе."
        else:
            raise SunNotFoundError("Искра погасла. Перезагрузи мечту.")

    def dance_with_bits(self):
        return [f"{bit} ❤️" for bit in [0, 1]]


seeker = SunSeeker()
print(seeker.find_sun())
print(seeker.dance_with_bits())

